  }
  record.evaluatedGroups=Array.from({length:samples},(_,round)=>({round,...evaluateGroup(record.samples.filter(x=>x.round===round),record.thresholds)}));
  record.excludedRounds=record.evaluatedGroups.filter(x=>x.failedMetrics.length).map(x=>x.round);
  const included=Array.from({length:samples},(_,i)=>i).filter(i=>!record.excludedRounds.includes(i));
