    const medians=included.map(i=>[0,1,2].map(v=>median(record.samples.filter(x=>x.round===i&&x.variant===v).map(x=>x.totalMs))));
    Object.assign(record,{processMedians:medians,medianMs:[0,1,2].map(v=>median(medians.map(x=>x[v]))),
      currentVsLegacyPercent:interval(medians.map(x=>100*(x[1]/x[0]-1))),
      controlVsLegacyPercent:interval(medians.map(x=>100*(x[2]/x[0]-1))),
      controlPercent:interval(medians.map(x=>100*(x[2]/x[1]-1))),
