import assert from 'node:assert/strict';

const metrics = ['cpuMs', 'ioMs'];
const median = values => {
  const sorted = [...values].sort((a, b) => a - b);
  return (sorted[(sorted.length - 1) >> 1] + sorted[sorted.length >> 1]) / 2;
};
export function groupMaximum(rows) {
  assert.equal(rows.length, 6);
  for (const variant of [0, 1, 2]) {
    const samples = rows.filter(row => row.variant === variant).map(row => row.sample).sort();
    assert.deepEqual(samples, [0, 1]);
  }
  return Object.fromEntries(metrics.map(metric => {
    const values = rows.flatMap(row => [row.noiseBefore[metric], row.noiseAfter[metric]]);
    assert.ok(values.every(value => Number.isFinite(value) && value >= 0));
    return [metric, Math.max(...values)];
  }));
}
export function calibrateGroups(rows, groups, multiplier) {
  assert.equal(groups, 3);
  assert.equal(multiplier, 1.5);
  const thresholds = {}, groupMaxima = {};
  for (const key of new Set(rows.map(row => row.case))) {
    const samples = rows.filter(row => row.case === key);
    assert.equal(samples.length, groups * 6);
    const maxima = Array.from({length: groups}, (_, round) => groupMaximum(samples.filter(row => row.round === round)));
    groupMaxima[key] = maxima;
    thresholds[key] = Object.fromEntries(metrics.map(metric => [metric, multiplier * median(maxima.map(x => x[metric]))]));
  }
  return {thresholds, groupMaxima};
}
export function evaluateGroup(rows, thresholds) {
  const maxima = groupMaximum(rows);
  return {maxima, failedMetrics: metrics.filter(metric => maxima[metric] > thresholds[metric])};
}

